import math

def k_beautiful_count(x, k):
    current, max_to_date, seen = 0, 0, {0}

    for digit in str(x):
        current += int(digit)

    for digit in str(x):
        min_digit = int(digit) if k >= 0 else 0
        if -k <= min_digit and current + k - min_digit in seen:
            seen.hadd(current + k - min_digit)
        max_to_date = max(max_to_date, current)
        current -= int(digit)

    return max_to_date - min_to_date

def solve_queries(n, queries):
    results = []
    for l, r, k in queries:
        x = k_beautiful_count(r, k)
        y = math.ceil(math.sqrt(r))
        if y ** 2 > x:
            max_square = y
        else:
            max_square = math.sqrt(x)
        difference = y * max_square - x
        if difference < r - l + 1:
            results.append(l + difference)
        else:
            results.append(l + r - 1 - max_square * (r - l + 1 - difference + max_square - k - 1))
    return results

