def apply_operations(n, operations):
    a = [0] * n
    i = 1
    while len(operations) > 0:
        x, y, z = operations[0]
        a[x-1], a[y-1], a[z-1] = 0, 0, 0
        a[i-1], a[i+1], a[i+2] = 0, 0, 0
        operations.pop(0)
    return a

def flip(l, n, side):
    half = n // 2
    left, right = min(n, half - l), max(0, l - half)
    position = (n - 1 - left) % 3
    if side == 1:
        return right + 3 * position
    else:
        return right + 3 * position - 1

