            return -1
        lengths[i] += current
        pages[i] += 1

    for i in range(len(lengths)):
        if i == 0:
            pass
        elif lengths[len(ais)-1] == x and pages[len(ais)-1] + 1 == len(ais) - 1:
            return len(ais)
        else:
            if lengths[len(ais[0]):i] != [0] * (i - len(ais)) or pages[len(ais[0]):i] != [0 if j == 0 else pages[j-1] for j in range(1, len(pages))]:
