from collections import defaultdict

MOD = 998244353

def count_partitions(n, parent):
    if n <= 1:
        return 1

    parent = list(parent)  # Convert to 0-based index
    root = 0  # Assuming root is 1
    stack = [root]

    while stack:
        node = stack.pop()
        children = []

        for child in range(1, n):
            if parent[child] == node:
                children.append(child)

        if len(children) > 0:
            stacks = stack + children
            if len(stacks) > 1:
                return (count_partitions(len(stacks)) - 1) % MOD
            elif len(stacks) == 1:
                return 0  # Leaves must be in different sets
            else:
                root = stacks[0]
                nodes = [1] + blocks if len(blocks) <= 1 else block_nodes(blocks)

    return 1

def block_nodes(nodes):
    blocks = defaultdict(list)
    stack = [ nodes.pop() ]

    while nodes:
        block = []
        for node in stack:
            while min(nodes) <= node:
                stack.append(nodes.pop())
            block.append(node)
        stack = []
        blocks[len(block) % 2].append(block)

    return len(blocks[0])

