def shortest_distance_to_largest_junction(n, m, roads):
    graph = [[] for _ in range(n)]
    for i in range(m):
        a, b, w = map(int, input().split())
        graph[a - 1].append((b - 1, w))
        graph[b - 1].append((a - 1, w))

    distances = [0.0] * n
    queue = [(0, -1, (sys.maxsize, 0))]  # (distance, previous junction, (largest distance, largest previous junction))

    while queue:
        current_dist, current_j, (largest_d, largest_p) = queue.pop()
        if current_j == -1:
            distances[current_dist] = max(distances[current_dist], largest_d, current_d)
        else:
            distances[current_dist] = max(distances[current_dist], largest_d, current_d)

            for neighbor, length in graph[current_j]:
                if distances[neighbor * -1] != -1:
                    neighbor_dist = current_dist - largest_d
                else:
                    queue.append((current_dist - largest_d + length, current_j, (largest_d, current_j)))
                if largest_d < current_dist - largest_p:
                    queue.append((largest_d + length, neighbor, (max(distances[neighbor * -1], largest_d), current_j)))

    return '{:.10f}'.format(max(distances) * 2 / n - 2 * (max(distances) * 2 / n - max(distances)))

