from collections import defaultdict

def construct_tree(n, constraints):
    adjacency_list = defaultdict(list)
    for i, j, d in constraints:
        if d == 'LEFT':
            adjacency_list[i].append(j)
        else:
            adjacency_list[i].append(j)

    # Helper function to trace back from a node to a common ancestor
    def find_common_ancestor(node):
        ancestors = {}
        while node in adjacency_list:
            ancestors[node] = node
            node = adjacency_list[node][0]
        ancestors[node] = -1
        for i in range(n + 1):
            if i in ancestors:
                ancestors[node] = max(ancestors[i], ancestors[node])
        return max(ancestors.values())

    # Check if there exists a tree that satisfies the constraints
    def check_tree(node, max_label):
        roots = set()
        while node in adjacency_list:
            max_label = max(max_label, node)
            if adjacency_list[node]:
                max_label = check_tree(max_label, find_common_ancestor(node))
            node = adjacency_list[node][0]
        node = 1
        while node < max_label:
            max_label = find_common_ancestor(node), max_label
            max_label = check_tree(max_label, find_common_ancestor(node))
            node = adjacency_list[node][0]
        roots.add(find_common_ancestor(node))
        roots.add(max_label)
        return len(roots) == 1

    for i in range(n + 1):
        if check_tree(i, n):
            return [i + 1]
    return "IMPOSSIBLE"

