def can_make_all_zeros(a):
    ones_count = a.count(1)
    if ones_count % 3 == 0 or ones_count % 3 == 1:
        return True
    return False

def find_arithmetic_progression(a):
    n = len(a)
    count = [[0]*n for _ in range(n)]

    for i in range(n):
        temp = a[i]
        for j in range(i+1, n):
            if a[j] == temp:
                count[i][j] = 1

    for i in range(n):
        for j in range(i, n):
            if count[i][j] and is_arithmetic(count, i, j):
                return (i, j)

    return None

def is_arithmetic(count, i, j):
    k = math.floor((i-j)/2)
    for x in range(k, j, 1):
        if not count[i+x][j] or not count[i][j+x]:
            return False
    return True

