import sys

def min_distance(junctions, roads):
    # Create a graph from the roads
    graph = {i: [] for i in range(junctions)}
    for u, v, w in roads:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))

    # Calculate the distances from each junction to all others
    dists = {junctions: {} for junctions in range(junctions)}
    for start in range(junctions):
        for end in range(junctions):
            if start == end:
                dists[start][end] = 0
                continue
            distances = sys.maxsize
            for current, weight in graph[start]:
                distances = min(distances, dists[current][end] + weight)
            dists[start][end] = distances

    # Calculate the shortest distance for each start junction
    result = min(dists[start][end] for start, end in dists.keys())
    return result

