from bisect import bisect_right

def count_substrings(text, k):
    pos = {''.join(sorted(text[i:i+k])): i for i in range(len(text)-k+1)}
    dp = [[0]*(len(text)+1) for _ in range(2)]
    dp[0][0] = -1
    dp[1][0] = -1
    for i in range(1, len(text)+1):
        if text[i-1] in pos:
            dp[(i-1)%2][i] = dp[i-pos[text[i-1]]%2][pos[text[i-1]]]

    if len(text) < k:
        return len(text) * (len(text) + 1) // 2

    q = []
    for t, i in dp[(len(text)-k)%2]:
        while q and q[-1] < i:
            q.pop()
        dp[(len(text)-k+1)%2][i] = q[-1] + (
            (1 if q[-1] == dp[(len(text)-k)%2][i-k]
             else (1+dp[(len(text)-k)%2][i-k], t)))[1]
        q.append(i)
    if dp[(len(text)-k+1)%2][i] == i:
        return i * (i+1) // 2
    else:
        t = dp[(len(text)-k+1)%2][i] + 1
        return bisect_right(q, t) - i * (i + 1) // 2 + dp[(len(text)-k)%2][t]

n, k = map(int, input().split())
words = []
for _ in range(n):
    word = input().strip()
    words.append(word)
result = [0] * n
for i, word in enumerate(words):
    result[i] = count_substrings(word, k)
print(" ".join(map(str, result)))
```

This Python program solves the problem by first counting the positions of each k-reversed substring in the input strings. It then iterates through each string's characters, updating prefix sums and using binary search (bisect_right) to count how many substrings are k-reversed. Finally, it prints the result for each input string.

