import sys

n = int(input())
queries = []

for _ in range(n):
    l, r, k = map(int, input().split())
    queries.append((l, r, k))

def is_k_beautiful(num, k):
    nums = [int(digit) for digit in str(num)]
    n = len(nums)
    dp = [False] * (n + 1)
    dp[0] = True

    for num in nums:
        for j in range(n, num - 1, -1):
            dp[j] |= dp[j | 1 << num]

    return dp[n]

def solution():
    result = []
    for l, r, k in queries:
        count = 0
        for num in range(l, r + 1):
            if is_k_beautiful(num, k):
                count += 1
        result.append(count)

    for answer in result:
        print(answer)

