from collections import defaultdict

def count_substrings(kMap, l, r):
    count = 0
    for i in range(l, r + 1):
        if kMap[i] >= k:
            count += 1
    return count

def main():
    n, k = map(int, input().split())
    strings = [input() for _ in range(n)]
    string_length = [len(s) for s in strings]
    kMap = defaultdict(int)
    for length in string_length:
        for i in range(length):
            kMap[i + length] += 1
            if (i + 1) in kMap:
                kMap[i + 1] += 1
            if i in kMap:
                kMap[i] += 1
    result = [0] * n
    for i, s in enumerate(strings):
        result[i] = sum(count_substrings(kMap, length, n) for length in string_length)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
